iconEnd?: React.ReactNode;
dir?: "rtl" | "ltr";
children?: React.ReactNode;
onClick?: React.MouseEventHandler<HTMLButtonElement>;
disabled?: boolean;
type?: "button" | "submit" | "reset";
className?: string;

dtsPropsFor.Card:
// Extends React.HTMLAttributes<HTMLDivElement> (onClick, style, id, …).
